begin;
select plan(40);
select set_config('test.amr',floor(extract(epoch from clock_timestamp()-interval '2 minutes'))::text,true);
insert into auth.users(id,aud,role,email,email_confirmed_at,created_at,updated_at) values
 ('d1100000-0000-4000-8000-000000000001','authenticated','authenticated','clinical-one@example.invalid',now(),now(),now()),
 ('d1100000-0000-4000-8000-000000000002','authenticated','authenticated','clinical-two@example.invalid',now(),now(),now());
insert into auth.identities(id,provider_id,user_id,identity_data,provider) select gen_random_uuid(),'clinical-'||right(id::text,1),id,jsonb_build_object('sub','clinical-'||right(id::text,1),'email',email,'email_verified',true),'google' from auth.users where id in('d1100000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000002');
insert into auth.sessions(id,user_id,created_at,aal) values ('d1200000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000001',now()-interval '3 minutes','aal2'),('d1200000-0000-4000-8000-000000000002','d1100000-0000-4000-8000-000000000002',now()-interval '3 minutes','aal2');
insert into auth.mfa_amr_claims(id,session_id,created_at,updated_at,authentication_method) select gen_random_uuid(),s.id,to_timestamp(current_setting('test.amr')::bigint),to_timestamp(current_setting('test.amr')::bigint),method from auth.sessions s cross join unnest(array['oauth','totp'])method where s.user_id in('d1100000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000002');
insert into public.organizations(id,code,name) values('d1300000-0000-4000-8000-000000000001','clinical-fixture','合成機構');
insert into public.branches(id,organization_id,code,name) values('d1400000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','one','合成分支甲'),('d1400000-0000-4000-8000-000000000002','d1300000-0000-4000-8000-000000000001','two','合成分支乙');
insert into public.profiles(id,display_name,kind) values('d1100000-0000-4000-8000-000000000001','合成交班者','staff'),('d1100000-0000-4000-8000-000000000002','合成接班者','staff');
insert into public.memberships(id,organization_id,branch_id,profile_id,status,starts_at) values('d1500000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000001','active',now()-interval '1 year'),('d1500000-0000-4000-8000-000000000002','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000002','active',now()-interval '1 year');
insert into public.membership_roles(membership_id,role_id) values('d1500000-0000-4000-8000-000000000001','10000000-0000-4000-8000-000000000003'),('d1500000-0000-4000-8000-000000000002','10000000-0000-4000-8000-000000000003');
insert into private.executive_access_policy(allowed_user_id,allowed_email,google_subject,enabled,approval_reference) values('d1100000-0000-4000-8000-000000000001','clinical-one@example.invalid','clinical-1',true,'Synthetic clinical test');
insert into private.staff_google_access_grants(allowed_user_id,organization_id,company_email_domain,allowed_email,google_subject,enabled,approval_reference) values('d1100000-0000-4000-8000-000000000002','d1300000-0000-4000-8000-000000000001','example.invalid','clinical-two@example.invalid','clinical-2',true,'Synthetic independent receiver');
insert into public.clients(id,organization_id,branch_id,client_code,display_name,admitted_on) values('d1600000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','CL-1','合成個案一',(now() at time zone 'Asia/Taipei')::date),('d1600000-0000-4000-8000-000000000002','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000002','CL-2','合成個案二',(now() at time zone 'Asia/Taipei')::date);
insert into public.care_records(id,organization_id,branch_id,client_id,record_key,category,occurred_at,data,created_by) values('d1700000-0000-4000-8000-000000000001','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000001','d1710000-0000-4000-8000-000000000001','staff/daily-care/care-diary',now(),'{}','d1100000-0000-4000-8000-000000000001');
create schema if not exists storage;create table if not exists storage.objects(id uuid primary key default gen_random_uuid(),bucket_id text not null,name text not null);
create function pg_temp.clinical_input(extra jsonb default '{}') returns jsonb language sql as $$select jsonb_build_object('clientId','d1600000-0000-4000-8000-000000000001','sourceKind','care_diary','sourceId','d1700000-0000-4000-8000-000000000001','sourceVersion',1,'label','合成照片','mimeType','image/png','fileSizeBytes',64,'sha256',repeat('a',64),'idempotency_key','d1800000-0000-4000-8000-000000000001')||extra$$;
create function pg_temp.reserve(extra jsonb default '{}') returns jsonb language sql as $$select receipt from public.reserve_clinical_attachment('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',pg_temp.clinical_input(extra))$$;
create function pg_temp.snapshot() returns jsonb language sql as $$select payload from public.clinical_attachments_snapshot('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000001','care_diary','d1700000-0000-4000-8000-000000000001')$$;
create function pg_temp.handoff_input(extra jsonb default '{}') returns jsonb language sql as $$select jsonb_build_object('action','create','clientId','d1600000-0000-4000-8000-000000000001','sourceRecordId','d1700000-0000-4000-8000-000000000001','ownerId','d1100000-0000-4000-8000-000000000002','message','合成交班內容','dueAt',clock_timestamp()+interval '1 day','idempotency_key','d1800000-0000-4000-8000-000000000002')||extra$$;
create function pg_temp.jwt(which integer) returns text language sql as $$select jsonb_build_object('sub','d1100000-0000-4000-8000-00000000000'||which,'session_id','d1200000-0000-4000-8000-00000000000'||which,'role','authenticated','aud','authenticated','aal','aal2','is_anonymous',false,'email',case which when 1 then 'clinical-one@example.invalid' else 'clinical-two@example.invalid' end,'iat',floor(extract(epoch from now())),'exp',floor(extract(epoch from now()+interval '30 minutes')),'amr',jsonb_build_array(jsonb_build_object('method','oauth','timestamp',current_setting('test.amr')::bigint),jsonb_build_object('method','totp','timestamp',current_setting('test.amr')::bigint)))::text$$;
select set_config('request.jwt.claims',pg_temp.jwt(1),true);
select ok((select bool_and(relrowsecurity and relforcerowsecurity) from pg_class where oid in('private.clinical_attachments'::regclass,'private.care_handoffs'::regclass,'private.family_messages'::regclass)),'new stores force RLS');
select ok(not has_table_privilege('authenticated','private.clinical_attachments','select,insert,update,delete'),'browser has no file metadata grants');
select ok(not has_function_privilege('authenticated','public.complete_clinical_attachment(uuid,text,text,text)','execute'),'browser cannot forge scanner');
set local role anon;select throws_ok($$select pg_temp.snapshot()$$,'42501',null,'anonymous attachments denied');reset role;set local role authenticated;
select is(pg_temp.reserve()->>'replayed','false','immutable upload reservation');
select is(pg_temp.reserve()->>'replayed','true','retry resolves same reservation');
select throws_ok($$select pg_temp.reserve('{"label":"changed"}')$$,'23505',null,'same key different payload denied');
select throws_ok($$select pg_temp.reserve('{"clientId":"d1600000-0000-4000-8000-000000000002"}')$$,'42501',null,'cross branch client denied');
select is(pg_temp.snapshot()->'rows'->0->>'canDownload','false','pending scanner never downloadable');
select is(pg_temp.reserve(jsonb_build_object('idempotency_key','d1800000-0000-4000-8000-000000000004','sha256',repeat('d',64)))->>'replayed','false','second pending upload for recovery');
reset role;select set_config('test.cancel_id',(select id::text from private.clinical_attachments where sha256=repeat('d',64)),true);
select set_config('test.cancel_input',jsonb_build_object('clientId','d1600000-0000-4000-8000-000000000001','sourceKind','care_diary','sourceId','d1700000-0000-4000-8000-000000000001','attachmentId',current_setting('test.cancel_id'),'idempotency_key','d1800000-0000-4000-8000-000000000005')::text,true);set local role authenticated;
select is((select receipt->>'cancelled' from public.cancel_clinical_attachment('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.cancel_input')::jsonb)),'true','pending upload safely cancelled without deleting original evidence');
select is((select receipt->>'id' from public.cancel_clinical_attachment('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.cancel_input')::jsonb)),current_setting('test.cancel_id'),'cancel retry same immutable evidence');
select throws_ok($$select public.cancel_clinical_attachment('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.cancel_input')::jsonb||jsonb_build_object('attachmentId','d1990000-0000-4000-8000-000000000001'))$$,'23505',null,'cancel key reused for another attachment denied');
reset role;select set_config('test.attachment',(select id::text from private.clinical_attachments where sha256=repeat('a',64)),true);
insert into storage.objects(bucket_id,name) select 'clinical-attachments',object_path from private.clinical_attachments where sha256=repeat('a',64);
select set_config('request.jwt.claims','{"role":"service_role"}',true);set local role service_role;
select is((select receipt->>'scanStatus' from public.complete_clinical_attachment(current_setting('test.attachment')::uuid,repeat('a',64),'clean','fixture-scanner')),'clean','scanner registration bound to private storage');
select throws_ok($$select public.complete_clinical_attachment(current_setting('test.attachment')::uuid,repeat('a',64),'infected','fixture-scanner')$$,'23505',null,'scan verdict cannot be rewritten');
reset role;select set_config('request.jwt.claims',pg_temp.jwt(1),true);set local role authenticated;
select is(pg_temp.snapshot()->'rows'->0->>'canDownload','true','clean exact-source attachment readable');
select is((select payload->>'expiresSeconds' from public.prepare_clinical_attachment_download('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000001','care_diary','d1700000-0000-4000-8000-000000000001',current_setting('test.attachment')::uuid)),'60','download expires in 60 seconds');
select throws_ok($$select pg_temp.reserve(jsonb_build_object('idempotency_key',gen_random_uuid()))$$,'23505',null,'duplicate clean content is flagged');
select throws_ok($$select public.care_handoff_write('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',pg_temp.handoff_input('{"ownerId":"d1100000-0000-4000-8000-000000000001"}'))$$,'42501',null,'sender cannot be independent recipient');
select set_config('test.handoff_input',pg_temp.handoff_input()::text,true);
select is((select receipt->>'version' from public.care_handoff_write('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.handoff_input')::jsonb)),'1','handoff created independently');
select is((select receipt->>'replayed' from public.care_handoff_write('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.handoff_input')::jsonb)),'true','handoff retry not duplicated');
reset role;select set_config('test.handoff_id',(select id::text from private.care_handoffs),true);
set local role authenticated;
select throws_ok($$select public.care_handoff_write('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',jsonb_build_object('action','acknowledge','clientId','d1600000-0000-4000-8000-000000000001','id',current_setting('test.handoff_id'),'expectedVersion',1,'note','','idempotency_key',gen_random_uuid()))$$,'42501',null,'sender cannot mark own handoff received');
select set_config('request.jwt.claims',pg_temp.jwt(2),true);
select is((select receipt->>'version' from public.care_handoff_write('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',jsonb_build_object('action','acknowledge','clientId','d1600000-0000-4000-8000-000000000001','id',current_setting('test.handoff_id'),'expectedVersion',1,'note','','idempotency_key',gen_random_uuid()))),'2','independent receiver acknowledges');
select is((select payload->'rows'->0->>'status' from public.care_handoff_snapshot('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000001')),'acknowledged','acknowledgement visible with actor and time');
select throws_ok($$select public.care_handoff_write('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',jsonb_build_object('action','close','clientId','d1600000-0000-4000-8000-000000000001','id',current_setting('test.handoff_id'),'expectedVersion',1,'note','完成追蹤','idempotency_key',gen_random_uuid()))$$,'40001',null,'stale followup version denied');
reset role;
insert into public.care_records(id,organization_id,branch_id,client_id,record_key,version,previous_version_id,category,status,occurred_at,data,signed_at,signed_by,signature_purpose,content_hash,created_by) values('d1700000-0000-4000-8000-000000000003','d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000001','d1710000-0000-4000-8000-000000000001',2,'d1700000-0000-4000-8000-000000000001','staff/daily-care/care-diary','signed',now(),'{}',now(),'d1100000-0000-4000-8000-000000000001','fixture signed',repeat('b',64),'d1100000-0000-4000-8000-000000000001');
select is((select count(*)::integer from private.clinical_attachment_links where source_id='d1700000-0000-4000-8000-000000000003'),1,'signed successor freezes existing clean reference');
select set_config('request.jwt.claims',pg_temp.jwt(1),true);set local role authenticated;
select throws_ok($$select pg_temp.reserve(jsonb_build_object('sourceId','d1700000-0000-4000-8000-000000000003','sourceVersion',2,'sha256',repeat('c',64),'idempotency_key',gen_random_uuid()))$$,'40001',null,'signed source rejects new attachments');
select is((select payload->>'clientId' from public.family_staff_workspace('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000001',null)),'d1600000-0000-4000-8000-000000000001','staff family workspace runtime uses selected client');
select is((select payload->'messages' from public.family_staff_workspace('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000001',null)),'[]'::jsonb,'staff cannot mix unselected families messages');
select throws_ok($$select public.family_staff_workspace('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000002')$$,'42501',null,'staff cannot select unconsented non-family recipient');
select set_config('test.family_publication',jsonb_build_object('clientId','d1600000-0000-4000-8000-000000000001','category','care','sourceId','d1700000-0000-4000-8000-000000000003','occurredAt',clock_timestamp(),'title','合成家屬摘要','summary','人工核准內容','idempotency_key','d1810000-0000-4000-8000-000000000001')::text,true);
select throws_ok($$select public.family_publish('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.family_publication')::jsonb)$$,'42501',null,'family disclosure requires recent recorded same-session reauthentication');
reset role;
insert into private.reauth_challenges(id,user_id,session_id,nonce_sha256,idempotency_key,issued_jwt_iat,created_at,expires_at,consumed_at,consumed_jwt_iat,factor_method,factor_verified_at)
values('d1820000-0000-4000-8000-000000000001','d1100000-0000-4000-8000-000000000001','d1200000-0000-4000-8000-000000000001',repeat('e',64),gen_random_uuid(),clock_timestamp()-interval '2 minutes',clock_timestamp()-interval '2 minutes',clock_timestamp()+interval '5 minutes',clock_timestamp()-interval '30 seconds',clock_timestamp()-interval '30 seconds','totp',clock_timestamp()-interval '30 seconds');
insert into private.reauth_events(user_id,session_id,challenge_id,aal,verification_method,verified_at)select user_id,session_id,id,'aal2','totp',factor_verified_at from private.reauth_challenges where id='d1820000-0000-4000-8000-000000000001';
set local role authenticated;
select is((select receipt->>'replayed' from public.family_publish('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.family_publication')::jsonb)),'false','authorized clinician publishes exact signed source');
select is((select receipt->>'replayed' from public.family_publish('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.family_publication')::jsonb)),'true','publication retry does not duplicate');
reset role;select set_config('test.family_withdraw',jsonb_build_object('clientId','d1600000-0000-4000-8000-000000000001','publicationId',(select id from private.family_publications),'reason','合成更正','idempotency_key','d1810000-0000-4000-8000-000000000002')::text,true);set local role authenticated;
select is((select receipt->>'replayed' from public.family_withdraw('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.family_withdraw')::jsonb)),'false','publication withdrawal preserves immutable copy');
select is((select receipt->>'replayed' from public.family_withdraw('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001',current_setting('test.family_withdraw')::jsonb)),'true','withdrawal retry does not duplicate');
select is((select payload->'publications'->0->>'withdrawn' from public.family_staff_workspace('d1300000-0000-4000-8000-000000000001','d1400000-0000-4000-8000-000000000001','d1600000-0000-4000-8000-000000000001',null)),'true','staff projection reads withdrawal chronology');
reset role;
select throws_ok($$update private.clinical_attachment_scans set verdict='infected'$$,'55000',null,'scan evidence is immutable');
select throws_ok($$delete from private.care_handoff_events$$,'55000',null,'handoff chronology is immutable');
select set_config('request.jwt.claims','{"role":"service_role"}',true);
update public.profiles set is_active=false where id='d1100000-0000-4000-8000-000000000001';
select set_config('request.jwt.claims',pg_temp.jwt(1),true);set local role authenticated;
select throws_ok($$select pg_temp.snapshot()$$,'42501',null,'disabled staff cannot read attachments on next statement');reset role;
select ok(exists(select 1 from public.audit_events where table_name='clinical_attachment_download') and exists(select 1 from public.audit_events where table_name='care_handoff_events'),'downloads and handoff writes audited');
select * from finish();rollback;
